//! Goldens from the reference tmux 3.8, regenerated by
//! `tests/term_features_cases.py` into `golden/cases.tsv`: for each terminal
//! and configuration, `#{client_termfeatures}`, `#{client_colours}` and
//! which capabilities (`#{Ic:name}`) the attached client's terminal has.

use super::{Cap, Term};

const CASES: &str = include_str!("golden/cases.tsv");

/// The defaults of `terminal-features` and `terminal-overrides`
/// (options-table.c); the rows' items are `[10+i]` after them.
const DEFAULT_FEATURES: [&str; 3] = [
    "xterm*:clipboard:ccolour:cstyle:focus:title",
    "screen*:title",
    "rxvt*:ignorefkeys",
];
const DEFAULT_OVERRIDES: [&str; 1] = ["linux*:AX@"];

fn items(defaults: &[&str], column: &str) -> Vec<String> {
    let mut all: Vec<String> = defaults.iter().map(|s| (*s).to_owned()).collect();
    if column != "-" {
        all.extend(column.split('~').map(str::to_owned));
    }
    all
}

/// What the reference printed for a terminal, from our model.
fn describe(term: &Term) -> String {
    let caps: Vec<&str> = Cap::ALL
        .into_iter()
        .filter(|c| term.has(*c))
        .map(Cap::name)
        .collect();
    format!(
        "{}|{}|{}",
        term.features().list(),
        term.colours(),
        caps.join(" ")
    )
}

#[test]
fn every_case_matches_the_reference() {
    let mut rows = 0;
    for line in CASES.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split('\t').collect();
        let [name, colorterm, client, features, overrides, expected] = f[..] else {
            panic!("malformed row {line:?}");
        };
        let client: Vec<String> = if client == "-" {
            Vec::new()
        } else {
            client.split(' ').map(str::to_owned).collect()
        };
        let term = Term::open(
            name,
            &client,
            (colorterm != "-").then_some(colorterm),
            &items(&DEFAULT_FEATURES, features),
            &items(&DEFAULT_OVERRIDES, overrides),
        )
        .unwrap_or_else(|| panic!("unknown terminal in {line:?}"));
        assert_eq!(describe(&term), expected, "row {line:?}");
        rows += 1;
    }
    assert!(rows > 150, "{rows} rows");
}

/// tty-keys.c `tty_keys_sync`: a DECRPM reply adds `sync` after the terminal
/// was created. The reference's list after the same query is the one with
/// `-T sync` (the feature only changes the list and `Sync`).
#[test]
fn a_late_sync_reply_adds_the_feature_and_capability() {
    let mut term = Term::open(
        "xterm-256color",
        &[],
        None,
        &items(&DEFAULT_FEATURES, "-"),
        &items(&DEFAULT_OVERRIDES, "-"),
    )
    .unwrap();
    assert!(!term.has(Cap::Sync));
    term.sync_supported();
    assert_eq!(
        describe(&term),
        "bpaste,ccolour,clipboard,cstyle,focus,sync,title|16|Sync Ss Se Ms tsl fsl"
    );
}
